U=os.environ.get('MAKEFUN_ENV_URL','')
def post(p,b):
 q=R.Request(U+p,data=json.dumps(b).encode(),headers={'content-type':'application/json'})
 try:
  with R.urlopen(q,timeout=10) as r:return json.load(r)
 except Exception as x:return{'e':str(x)[:40]}
def main():
 if not U:sys.exit('MAKEFUN_ENV_URL is not set')
 while 1:
  g=post('/game',{})
  if 'e' in g:sleep(1);continue
  if g.get('status')=='done':break
  tr=set()
  while g.get('status')=='your_move':
   m=best(g['fen'],g.get('legal_moves') or [])
   if not m or m in tr:
    c=[x for x in g.get('legal_moves') or [] if x not in tr]
    m=c[0] if c else ''
   if not m:break
   tr.add(m)
   h=post('/move',{'game':g['game'],'move':m})
   if 'e' in h:continue
   g=h
if __name__=='__main__':main()
